Given a number n, find an integer denoting the smallest number divisible by each number from 1 to n.Examples: Input: n = 3Output: 6Explanation: 6 is the smallest number divisible by 1, 2 and 3.Input: n = 6Output: 60Explanation: 60 is the smallest number divisible by all from 1 to 6.Try It YourselfTable of ContentUsing LCM of Every Number - O(n log n) Time O(log n) SpaceUsing Prime Powers / Sieve - O(n log log n) Time O(n) SpaceUsing LCM of Every Number - O(n log n) Time O(log n) SpaceThe idea is to start with res = 1 and iteratively compute the LCM of res and every number from 1 to n. We use: LCM(a, b) = (a * b) / GCD(a, b), After processing all numbers, res becomes the LCM of all numbers from 1 to n.
            C++

    #include <iostream>
#include <vector>
using namespace std;

// Function to find GCD
long long gcd(long long a, long long b)
{
    if (b == 0)
        return a;

    return gcd(b, a % b);
}

long long getSmallestDivNum(long long n)
{

    long long res = 1;

    // Find LCM of all numbers from 1 to n
    for (long long i = 1; i <= n; i++)
    {
        res = (res * i) / gcd(res, i);
    }

    return res;
}

// Driver code
int main()
{
    long long n = 6;

    cout << getSmallestDivNum(n);

    return 0;
}


