Output60Using Prime Powers / Sieve - O(n log log n) Time O(n) SpaceThe idea is to use the fact that the LCM of numbers from 1 to n contains the highest power of every prime that does not exceed n. For every prime p ≤ n: Find the largest power p^k such that p^k ≤ n.  Multiply all such powers together.Let us understand with example:For n = 6: Highest power of 2 ≤ 6 is 2^2 which is 4  Highest power of 3 ≤ 6 is 3*1 which 3  Highest power of 5 ≤ 6 is 5*1 which is 5 LCM = 4 × 3 × 5 = 60
            C++

    #include <iostream>
#include <vector>
using namespace std;

long long getSmallestDivNum(long long n)
{

    vector<bool> isPrime(n + 1, true);

    // Build Sieve of Eratosthenes
    isPrime[0] = false;

    if (n >= 1)
        isPrime[1] = false;

    for (long long i = 2; i * i <= n; i++)
    {
        if (isPrime[i])
        {
            for (long long j = i * i; j <= n; j += i)
            {
                isPrime[j] = false;
            }
        }
    }

    long long lcm = 1;

    // Process every prime
    for (long long i = 2; i <= n; i++)
    {
        if (isPrime[i])
        {
            long long power = i;

            // Find highest power of prime <= n
            while (power <= n / i)
            {
                power *= i;
            }

            lcm *= power;
        }
    }

    return lcm;
}

// Driver code
int main()
{
    long long n = 6;

    cout << getSmallestDivNum(n);

    return 0;
}


